//! Closed XG19 / TK003. Targets and modes are declared before payment.
use crate::{engine::RuleResult,model::*,rules::*,catalog};
use std::collections::BTreeSet;
pub(crate) const ID:&str="XG19";
pub(crate) const TOKEN:&str="TK003";
pub(crate) const KEY:&str="xg19-negotiation";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
fn hidden()->TargetSlotSpec{target(Zone::Board,EntityKind::Hidden,Relation::Any,Range::Anywhere)}
pub(crate) fn definition(id:&str)->Definition{if id==TOKEN{let mut d=with_abilities(vec![]);d.traits.public=true;return d;}let mut a=ability(KEY,"枪火谈判：声明地区、模式及暗藏者目标",Timing::Standard,vec![],vec![],vec![],None);a.play_only=true;a.modes=[("destroy","消灭至多两个目标暗藏者",0),("generate","生成两个警察",1),("both","消灭暗藏者并生成两个警察",2)].into_iter().map(|(key,label,mode)|Mode{key:key.into(),label:label.into(),targets:vec![region()],ops:vec![Op::XG19Resolve{mode,exposure:None}]}).collect();with_abilities(vec![a])}
fn selected()->Vec<AbilitySpec>{let a=definition(ID).abilities.remove(0);let mut out=vec![a.clone()];for m in &a.modes{let mut b=a.clone();b.targets=m.targets.clone();b.ops=m.ops.clone();b.modes.clear();out.push(b);}out}
fn owns(o:&Op)->bool{match o{Op::XG19Resolve{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("xg19-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!selected().iter().any(|b|same(a,b)){return Err("枪火谈判须保留原模式和目标定义".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(matches!(id,ID|TOKEN)||d.abilities.iter().any(related))&&(!matches!(id,ID|TOKEN)||!same(d,&definition(id))){return Err("枪火谈判/警察定义不可移植或删改".into());}Ok(())}
fn related_frame(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("xg19-")||f.steps.iter().any(|s|owns(&s.op))}
impl Game {
 fn xg19_both(&self,actor:usize,exposure:&[u32])->bool{exposure.iter().enumerate().any(|(s,n)|self.team(s)!=self.team(actor)&&*n>=2)}
 pub(crate) fn xg19_action(&self,actor:usize,c:&Card,a:&Action)->RuleResult<()>{if c.definition!=ID{return Ok(());}let mode=a.option.as_deref().ok_or("须先选择枪火谈判模式")?;let both=self.xg19_both(actor,&self.players.iter().map(|p|p.society_zone.exposure).collect::<Vec<_>>());if !matches!(mode,"destroy"|"generate"|"both")||both!=(mode=="both")||a.ability_id.as_deref().is_some_and(|k|k!=KEY)||*a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),option:a.option.clone(),region:a.region,selected:if mode!="generate"{a.selected.clone()}else{None},..Action::new("play")}){return Err("枪火谈判须按声明时公开标志选择原模式和完整目标".into());}Ok(())}
 pub(crate) fn xg19_candidates(&self,actor:usize,c:&Card)->Vec<(Action,String)>{let source=self.source_snapshot(c,None);let both=self.xg19_both(actor,&self.players.iter().map(|p|p.society_zone.exposure).collect::<Vec<_>>());let mut out=vec![];for r in 0..self.regions.len(){if !self.valid_binding(actor,&source,&region(),&format!("region:{r}")){continue;}let ids=self.regions[r].cards.iter().filter(|c|self.valid_binding(actor,&source,&hidden(),&c.id)).map(|c|c.id.clone()).collect::<Vec<_>>();let mut subsets=vec![vec![]];for i in 0..ids.len(){subsets.push(vec![ids[i].clone()]);for j in i+1..ids.len(){subsets.push(vec![ids[i].clone(),ids[j].clone()]);}}for mode in if both{vec!["both"]}else{vec!["destroy","generate"]}{for selected in if mode=="generate"{vec![None]}else{subsets.iter().cloned().map(Some).collect()}{let label=format!("枪火谈判：{} · 地区{} · 暗藏者 {}",match mode{"destroy"=>"消灭暗藏者","generate"=>"生成警察",_=>"两项全选"},r+1,selected.as_ref().map_or("无".into(),|ids|ids.join("、")));out.push((Action{card_id:Some(c.id.clone()),ability_id:Some(KEY.into()),option:Some(mode.into()),region:Some(r),selected,..Action::new("play")},label));}}}out}
 pub(crate) fn xg19_bind(&self,actor:usize,source:&SourceSnapshot,spec:&AbilitySpec,a:&Action)->RuleResult<Vec<BoundTarget>>{validate_ability(ID,spec)?;self.xg19_action(actor,&source.card,a)?;let r=a.region.filter(|r|*r<self.regions.len()).ok_or("枪火谈判缺少地区")?;let rid=format!("region:{r}");if !self.valid_binding(actor,source,&region(),&rid){return Err("枪火谈判地区无效".into());}let mut out=vec![BoundTarget{id:rid.clone(),spec:region(),region_instance:Some(self.regions[r].card.id.clone()),public:self.public_target(actor,source,&region(),&rid)}];if a.option.as_deref()!=Some("generate"){let ids=a.selected.as_ref().filter(|ids|ids.len()<=2&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()).ok_or("须声明零至两个不同暗藏者")?;for id in ids{if !self.board(id).is_some_and(|(at,_)|at==r)||!self.valid_binding(actor,source,&hidden(),id){return Err("暗藏者须在原目标地区".into());}out.push(BoundTarget{id:id.clone(),spec:hidden(),region_instance:None,public:self.public_target(actor,source,&hidden(),id)});}}Ok(out)}
 pub(crate) fn xg19_targets_current(&self,f:&ResolutionFrame)->bool{f.source.card.definition!=ID||f.targets.iter().skip(1).all(|t|self.board(&t.id).is_some_and(|(r,c)|Some(r)==f.chosen_region&&c.face_down))}
 pub(crate) fn validate_xg19_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !related_frame(f){return Ok(());}self.validate_resource_frame(f)?;let c=&f.source.card;let [Step{context,op:Op::XG19Resolve{mode,exposure:Some(exposure)}}]=f.steps.as_slice()else{return Err("枪火谈判缺少原模式及声明时公开观察".into());};if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||c.face_down||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.play_source.is_some()||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()||f.ability_key!=KEY||*context!=f.actor||*mode>2||exposure.len()!=self.players.len()||self.xg19_both(f.actor,exposure)!=(*mode==2)||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=3&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_valid(id))){return Err("枪火谈判来源、模式或费用阶段损坏".into());}if f.targets.is_empty()||f.targets.len()>3||*mode==1&&f.targets.len()!=1{return Err("枪火谈判目标数量损坏".into());}let t=&f.targets[0];let r=f.chosen_region.filter(|r|*r<self.regions.len()).ok_or("原地区缺失")?;if t.id!=format!("region:{r}")||!same(&t.spec,&region())||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||t.public.kind!="region"||t.public.region!=Some(r){return Err("枪火谈判原地区身份损坏".into());}let mut seen=BTreeSet::new();for t in &f.targets{if !seen.insert(&t.id)||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("枪火谈判原目标快照损坏".into());}}for t in f.targets.iter().skip(1){if !same(&t.spec,&hidden())||t.region_instance.is_some()||t.public.region!=Some(r)||!self.mystic_instance_valid(&t.id){return Err("枪火谈判暗藏者原目标损坏".into());}}self.mobility_immutable_identity(c)}
 pub(crate) fn validate_xg19_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(related_frame){let f=i.frame.as_ref().ok_or("枪火谈判实际事务缺帧")?;self.validate_xg19_frame(f)?;if f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("枪火谈判实际事务与原帧不符".into());}}Ok(())}
 pub(crate) fn xg19_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_xg19_frame(f)?;if f.cursor!=1{return Err("枪火谈判须经原目标守卫".into());}let Op::XG19Resolve{mode,..}=f.steps[0].op else{unreachable!()};if self.players[f.actor].eliminated{return Ok(());}if mode!=1{let wave=f.targets.iter().skip(1).filter_map(|t|self.board(&t.id).map(|(r,c)|(c.id.clone(),RemovalCause::Destroy,self.source_snapshot(c,Some(r))))).collect();self.destroy_wave_as(f.actor,wave);}if mode!=0{let r=f.chosen_region.unwrap();if self.region_live(r)&&f.targets[0].region_instance.as_ref()==Some(&self.regions[r].card.id){for _ in 0..2{let c=self.make_generated(crate::generated::GeneratedKind::Police,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,TOKEN,&id,false);}}}Ok(())}
 pub(crate) fn validate_xg19_state(&self)->RuleResult<()>{let mut ids=BTreeSet::new();for i in &self.stack{self.validate_xg19_play(i)?;self.validate_xg19_token_play(i)?;if let Some(f)=&i.frame{if f.source.card.definition==TOKEN&&f.ability_key!="reveal"&&!self.validated_mobility_frame(f)?{return Err("警察不能借用其他角色能力帧".into());}self.validate_xg19_frame(f)?;if related_frame(f)&&!ids.insert(&f.frame_id){return Err("枪火谈判同帧重复".into());}}}for e in &self.effects{match e{Effect::Frame{frame}if related_frame(frame)=>return Err("枪火谈判单步不能保留游离续体".into()),Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("枪火谈判没有触发声明".into()),_=>{}}}if self.pending.as_ref().is_some_and(|p|match &p.resolution{ChoiceResolution::Frame{frame,..}=>related_frame(frame),ChoiceResolution::Declare{declaration:d,..}=>d.source.card.definition==ID||related(&d.ability),_=>false}){return Err("枪火谈判目标须在支付前完整声明".into());}Ok(())}
}

impl Game {
 pub(crate) fn validate_xg19_token_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|matches!(c.definition.as_str(),TOKEN))&&!item.frame.as_ref().is_some_and(|f|matches!(f.source.card.definition.as_str(),TOKEN)&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("TK003角色事务缺少原帧")?;let c=&f.source.card;
  if !matches!(c.definition.as_str(),TOKEN)||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=8&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("TK003角色事务、原帧或实际牌面不符".into());}if (f.ability_key!="reveal" || f.money_units(0)!=0 || !f.resource_payments.is_empty() || !matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if ids.is_empty())) {return Err("警察只接受真实零费现身事务".into());} self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)
 }
}
